#!/usr/bin/env python3
"""KALE editorial expansion: offline, original Turkish practical cards. No scraped prose."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
FILE=ROOT/'data/content.json'
source=json.loads(FILE.read_text(encoding='utf-8'))
base=[e for e in source['entries'] if int(e['id'])<=37]
more=[]
references={
 'AFAD':'https://hazirim.gov.tr/tr/afetler/deprem',
 'AFAD_TOPLANMA':'https://www.turkiye.gov.tr/afet-ve-acil-durum-yonetimi-acil-toplanma-alani-sorgulama',
 'CDC_SU':'https://www.cdc.gov/water-emergency/about/index.html',
 'CDC_FILTRE':'https://www.cdc.gov/drinking-water/prevention/water-treatment-hiking-camping-traveling.html',
 'WHO_ISHAL':'https://www.who.int/news-room/fact-sheets/detail/diarrhoeal-disease',
 'AHA':'https://cpr.heart.org/en/resuscitation-science/2024-first-aid-guidelines',
}
def add(cat,title,body, tags='', region=None, ref=None, priority='normal'):
    idx=38+len(more)
    more.append({'id':idx,'category':cat,'title':title,'body':body.replace(' | ','\n'),
       'tags':tags or title,'warning':'','diagram':'','review_status':'taslak—uzman onayı bekliyor',
       'last_reviewed':None, 'sources':[references[i] for i in (ref or [])],
       'regions':region or [], 'priority':priority, 'origin':'KALE editoryal taslak'})
# Safeguards: no unsupported species identification; no speculative prescriptions.
# ACIL / risk preparedness
add('ACİL','Deprem sırasında güvenli hareket','Sarsıntı sırasında pencere, merdiven ve balkondan uzak dur. | Sağlam bir eşya yanında/altında çök-kapan-tutun uygula; sarsıntı bitene dek bulunduğun güvenli konumu koru. | Sarsıntı durunca binanın hasar ve gaz/elektrik risklerini değerlendir; güvenli çıkış varsa tahliye et.','deprem çök kapan tutun',ref=['AFAD'],priority='yüksek')
add('ACİL','Deprem sonrası bina değerlendirme','Kolon-kirişte ciddi hasar, göçme, yangın, gaz kokusu veya yoğun çatlama varsa binadan uzaklaş. | Hasarlı yapıya eşya almak için geri dönme. Artçı sarsıntıları hesaba kat. | Yetkili ekipler incelemeden yapıyı güvenli kabul etme.','deprem bina hasar artçı',ref=['AFAD'],priority='yüksek')
add('ACİL','Yangında ilk kararlar','Duman veya alevin bulunduğu yere yaklaşma; güvenli çıkış yönünü seç. | Kapılar sıcaksa açma; dumanlı alanları mümkünse terk et. | Dışarı çıktıktan sonra tekrar içeri girme ve 112 ile iletişime geç.','yangın duman tahliye 112',priority='yüksek')
add('ACİL','Sel ve ani taşkından kaçınma','Dere yatağı, menfez, alt geçit ve su biriken çukurda bekleme. | Akıntıya girme ve su basmış yoldan araçla geçme; suyun derinliği/zemin durumu bilinmez. | Daha yüksek ve güvenli yere çık, yönlendirmeleri izle.','sel taşkın dere akıntı',priority='yüksek')
add('ACİL','Tsunami ihtimalinde kıyıdan uzaklaşma','Şiddetli/uzun kıyı depremi, denizin aniden çekilmesi veya güçlü uğultu uyarı işareti olabilir. | Kıyıdan ve alçak sahil kesiminden derhal uzaklaş, yüksek bölgeye veya resmî tahliye güzergâhına yönel. | İlk dalgadan sonra geri dönme; resmî açıklamayı bekle.','tsunami kıyı deniz deprem',priority='yüksek')
add('ACİL','72 saatlik temel ihtiyaç planı','Kişi sayısını, suyu, mevcut gıdayı, ilaçları, aydınlatmayı ve iletişim seçeneklerini yaz. | Su, kuru kalma, ısı dengesi, hijyen ve ilk yardım malzemelerini önceliklendir. | Her gün envanteri güncelle; elindeki malzemelere göre tüketimi planla.','72 saat afet çantası plan',ref=['AFAD'])
add('ACİL','Aile buluşma ve haberleşme planı','Mahallenin resmî toplanma alanını afet öncesinde öğren ve çevrimdışı kaydet. | Aileyle iki buluşma noktası ve şehir dışı irtibat kişisi belirle. | Telefon iletişimi sıkışırsa kısa SMS kullan; acil hatları gereksiz meşgul etme.','aile buluşma toplanma alanı',ref=['AFAD_TOPLANMA'])
add('ACİL','Çocuk ve yaşlılarla tahliye','İlaç, gözlük, kimlik ve zorunlu destek ekipmanlarını hızlı erişim çantasına koy. | Yürüyemeyen veya engelli kişinin destek ihtiyacını önceden planla. | Tahliye sırasında grubu ayırma; her kişi için sorumlu belirle.','çocuk yaşlı engelli tahliye')
add('ACİL','Kapalı alanda gaz kokusu','Ateş veya kıvılcım oluşturma; elektrik anahtarı ve prizlerle oynama. | Güvenliyse vanayı kapat; ortamı terk et. | Binadan uzak, güvenli bir noktada yetkili gaz acil servisine ve gerektiğinde 112’ye haber ver.','doğalgaz kaçak gaz kokusu',priority='yüksek')
add('ACİL','Enkaz altında mahsur kalma','Tozdan ağzı-burnu koru; gereksiz hareketle çevreyi oynatma. | Uygunsa telefon/SMS, düdük veya belirli aralıklarla yüzeye vurma ile yerini bildir. | Sürekli bağırmak yerine nefes ve enerjini korumaya çalış; ateş yakma.','enkaz mahsur düdük')
# Shelter
add('BARINAK','Barınak yeri seçimi kontrol listesi','Kuru, nispeten düz ve yamaç/çökme tehdidinden uzak zemin ara. | Dere yatağı, sel çizgisi, gevşek kaya, ölü dal, devrilebilir ağaç ve elektrik hattından uzak dur. | Rüzgâr, yağmur yönü, tahliye güzergâhı ve yasal erişimi kontrol et.','yer seçimi sel kaya ağaç')
add('BARINAK','Branda ile alçak sığınak','İki güvenli sabitleme noktası arasında sağlam bir ip ger. | Brandayı gergin biçimde çatı gibi sabitle; yağmurun kenarlardan akacağı açı bırak. | Zemini su akışından uzak ve yalıtımlı tut; çıkışı hiçbir zaman kilitleme.','branda tarp ip düğüm')
add('BARINAK','İple temel düğümler','İzbarço, camadan ve kazık bağını ne zaman kullandığını görsel kılavuzla çalış. | Önce güvenli yük taşımayan düşük riskli kullanımlarda dene. | Tırmanış, kurtarma ve insan taşıma için eğitimli değilsen doğaçlama düğüme güvenme.','ip düğüm izbarço camadan')
add('BARINAK','Zemine karşı ısı kaybını azaltma','Soğuk zemin doğrudan temasla hızlı ısı kaybına neden olur. | Mat, köpük, kuru karton veya güvenli kuru yalıtım katmanları kullan. | Islak yaprak, küflü malzeme ve böcek yoğun alanlardan kaçın.','zemin izolasyon mat uyku')
add('BARINAK','Yağmurlu alanda kuru uyku bölgesi','Zemindeki suyun akış yönünü incele; su biriken çukurda yatma. | Dış kabuğu su geçirmez yaparken içeride yoğuşmayı azaltacak kontrollü havalandırma bırak. | Uyku tulumu ve kuru iç kıyafeti ayrı poşette koru.','yağmur barınak yoğuşma')
add('BARINAK','Şiddetli rüzgârda barınak','Rüzgâra geniş yüzey sunmayan alçak barınak seç; direk ve kazıkları denetle. | Kopabilecek tabelaların, devrilebilecek ağaçların ve gevşek çatıların altına sığınma. | Hızla kötüleşen havada sağlam bina veya resmî barınma alanı daha güvenlidir.','rüzgar fırtına barınak')
add('BARINAK','Sıcak havada gölge ve havalandırma','Gölge ve hava hareketi olan alan seç; güneş alan kapalı araç ve çadırda kalma. | Yeterli güvenli suya erişimi ve gölgede dinlenmeyi öncele. | Baş dönmesi, bilinç değişikliği veya aşırı ısınma belirtilerinde tıbbi yardım ara.','sıcak güneş gölge')
add('BARINAK','Kış barınağında havalandırma','Rüzgârdan korunurken hava akışını tamamen kesme. | Kapalı çadır, araç veya sığınak içinde kömür, mangal, jeneratör, kamp ocağı kullanma: karbonmonoksit ölümcüldür. | Kuru katmanlar ve zemin yalıtımıyla ısıyı koru.','kış çadır karbonmonoksit',priority='yüksek')
add('BARINAK','Barınaktan acil çıkış','Gece karanlığında bulunabilecek açık bir çıkış oluştur. | Keskin alet ve sıcak yüzeyleri kapı önünden uzaklaştır. | Şiddetli yağmur, yangın veya ani su baskını için alternatif kaçış yönünü önceden belirle.','tahliye çıkış barınak')
# Water
add('SU','Su kaynaklarında risk sıralaması','Mümkünse kapalı ambalajlı ve güvenilir suyu kullan. | Kaynağı bilinmeyen dere, gölet ve açık depolarda mikrop, hayvan dışkısı, kimyasal ve tarımsal atık riski vardır. | Berrak görünmesi suyun güvenli olduğu anlamına gelmez.','içme suyu kaynak temiz',ref=['CDC_SU'],priority='yüksek')
add('SU','Yağmur suyu toplama güvenliği','Temiz bir toplama yüzeyi ve temiz kap kullan; ilk akış yüzey kiri taşıyabilir. | Çatı malzemesinin, kuş dışkısının ve çevre kirliliğinin riskini düşün. | Yağmur suyunu içilecekse uygun arıtma/dezenfeksiyon olmadan güvenli kabul etme.','yağmur suyu toplama')
add('SU','Çamurlu suyu ön arıtma','Suyu bir süre dinlendirip tortunun çökmesini sağla. | Üstteki daha berrak kısmı dikkatle al veya temiz bezden geçir. | Bu işlem mikropları yok etmez; sonrasında uygun dezenfeksiyon gerekir.','çamurlu bulanık çökeltme',ref=['CDC_SU'])
add('SU','Kaynatma ve kimyasal kirlilik ayrımı','Kaynatmak mikropları öldürmeye yardımcıdır; kimyasal zehri, yakıtı ve ağır metalleri güvenilir biçimde gidermez. | Yakıt/kimyasal şüpheli suyu kullanma; başka kaynak bul. | Filtre ve tabletin hangi tehlikeyi giderdiğini etiketinden kontrol et.','kaynatma kimyasal ağır metal',ref=['CDC_SU'],priority='yüksek')
add('SU','Yüksek rakımda kaynatma süresi','Berrak suyu kuvvetli kaynamaya getir. | CDC, yaklaşık 2.000 m üzerindeki rakımlarda 3 dakika, daha alçak yerlerde 1 dakika kaynatmayı önerir. | Suyu kapalı temiz kapta soğutup sakla; kimyasal kirlenme varsa kaynatmak yeterli değildir.','yüksek rakım kaynatma dakika',ref=['CDC_SU'])
add('SU','Taşınabilir su filtrelerinde etiket','Gözenek boyu ve üretici iddialarını incele; bazı filtreler parazitleri giderirken virüsleri gidermez. | Filtre sonrası uygun dezenfeksiyon gerekebilir. | Filtre elemanının bakım ve ömrüne ilişkin talimatları izle.','su filtresi virüs bakteri',ref=['CDC_FILTRE'])
add('SU','Su depolama kaplarını ayırma','İçme suyu kaplarını yakıt, kimyasal veya temizlik malzemesi kaplarından ayrı tut. | Temiz bir kapak kullan; kabın içine kirli kepçe/el sokma. | İçme suyu ile temizlik suyunu belirgin şekilde etiketle.','su kabı depolama hijyen')
add('SU','Su kullanım önceliği','İçme, gerekli yiyecek hazırlama, ağız bakımı ve hayati hijyen için güvenli suyu ayır. | Kişi sayısı, sıcaklık ve aktiviteye göre ihtiyacı her gün yeniden değerlendir. | Şüpheli su tüketerek susuzluğu çözmeye çalışma.','su plan öncelik')
add('SU','İshalde susuzluk belirtileri','Ağız kuruluğu, çok az/koyu idrar, belirgin halsizlik ve sersemlik sıvı kaybına işaret edebilir. | Bilinç değişikliği, su içememe veya ağır halsizlik acildir; tıbbi yardım iste. | Özellikle çocuklarda ve yaşlılarda gecikme tehlikelidir.','ishal dehidrasyon susuzluk',ref=['WHO_ISHAL'],priority='yüksek')
add('SU','Su kesintisinde hijyen','Ellerin temizliğinde güvenilir su ve sabun kullan; mümkün değilse uygun el antiseptiği yararlı olabilir. | Tuvalet ve yemek hazırlama alanını ayır. | Güvenli suyu açık yaraya veya göze kirli kapla taşımamaya dikkat et.','su kesintisi el hijyeni')
# Heat
add('ATEŞ','Karbonmonoksit tehlikesi','Karbonmonoksit kokusuzdur. Jeneratör, mangal veya yakıtlı ısıtıcıyı kapalı/yarı kapalı ortamda kullanma. | Baş ağrısı, bulantı ve sersemlik şüphe yaratabilir; güvenliyse temiz havaya çık ve 112’yi ara. | Gaz şüphesi olan yere kurtarmak için korumasız girme.','karbonmonoksit soba mangal jeneratör',priority='yüksek')
add('ATEŞ','Katmanlı giyinme sistemi','İç katman teri uzaklaştırmalı; orta katman yalıtmalı; dış katman rüzgâr ve yağıştan korumalıdır. | Islanmış kıyafetleri güvenli ortamda çıkarıp kuru katmanlarla değiştir. | Aşırı terlemenin sonrasında soğuma yaratmasına dikkat et.','katman içlik yağmurluk sıcaklık')
add('ATEŞ','Baş, el ve ayakların korunması','Islak çorap ve eldiveni kuru malzemeyle değiştir; kan dolaşımını bozacak kadar sıkı sarmadan koru. | Donma şüphesinde bölgeyi ovalama ve doğrudan ateşe tutma. | Uyuşma, sertleşme veya renk değişikliğinde sağlık yardımı iste.','donma el ayak baş soğuk',ref=['AHA'])
add('ATEŞ','Yağışta güvenli ateş alanı','Açık havada dahi rüzgârın taşıdığı kıvılcımları, çevredeki kuru otları ve orman yangını riskini gözet. | Yerel yangın yasaklarına uy ve kontrol edemeyeceğin ateşi başlatma. | Su veya uygun söndürücü hazır tut; ayrılmadan tamamen söndür.','ateş yağmur kıvılcım')
add('ATEŞ','Hipotermi ilk müdahale','Kişiyi rüzgârdan ve ıslaklıktan uzaklaştır; ısı kaybını azalt. | Bilinci bulanıksa ağızdan yiyecek/içecek verme; 112 çağır. | Elleri/ayakları sertçe ovalama, aşırı sıcak su kullanma.','hipotermi soğuk bilinç',ref=['AHA'],priority='yüksek')
add('ATEŞ','Isı kaybında rüzgârın etkisi','Rüzgâr vücudun çevresindeki sıcak hava katmanını kaldırarak daha hızlı soğutabilir. | Rüzgâr kesen ama havalandırmayı bütünüyle engellemeyen katman kullan. | Dinlenirken ıslak giysi ve zemine doğrudan temastan kaçın.','rüzgar soğuk ısı kaybı')
add('ATEŞ','Güvenli aydınlatma','Mümkünse LED el feneri/kafa lambası kullan; yedek pil bulundur. | Mum ve açık alevi çadır, uyku alanı ve çocukların yakınında bırakma. | Bataryaları metal eşyalarla kısa devre ettirme.','fener led mum pil')
# Food
add('GIDA','Gıda güvenliği: şüpheli konserveler','Şişmiş, sızıntılı, paslı veya kapağı şüpheli konserveyi tüketme. | Görünümü ve kokusu normal olsa bile bazı tehlikeler anlaşılmaz. | Şüpheli gıdayı tat testi yaparak değerlendirme.','konserve botulizm gıda')
add('GIDA','Soğutma kesintisinde bozulabilir yiyecek','Buzdolabının kapağını gereksiz açma; bozulabilir gıdaların sıcaklıkta geçirdiği süreyi izle. | Koku ve tat güvenilir test değildir. | Şüpheli et, süt ürünleri ve pişmiş yemekleri tüketme.','buzdolabı elektrik kesintisi')
add('GIDA','Kuru gıda stoklama','Pirinç, bulgur, bakliyat gibi kuru yiyecekleri temiz, kuru, haşereye karşı kapalı kaplarda sakla. | Ambalaj açılış ve son kullanma tarihini etiketle. | Önce eski stokları kullan; nem, küf ve kemirgen izlerini kontrol et.','bakliyat kuru gıda stok')
add('GIDA','Pişmiş gıdada çapraz bulaşma','Çiğ et ve balıkla temas eden bıçak/tahta/elleri pişmiş gıdayla temas ettirme. | Temiz su ve sabunla ekipmanı yıka. | Eşit pişmeyen büyük parçaların içi güvenli sıcaklığa ulaşmamış olabilir.','pişirme çiğ çapraz bulaşma')
add('GIDA','Az yakıtla pişirme','Kapaklı tencere kullan, malzemeyi küçük parçalar hâline getir ve uygun miktarda su koy. | İç mekânda kamp ocağı veya mangal yakma. | Güvenli gıda sıcaklığından taviz verme; yarı pişmiş et yemekten kaçın.','yakıt tasarrufu pişirme')
add('GIDA','Balık tutmada basit ekipman','Uygun, yasal av sezonu ve boy sınırlarını kontrol et. | El oltası, uygun misina ve kanca gibi basit düzeneklerle güvenli kıyıdan olta atılabilir. | Akıntılı suya, kaygan kayaya ve taşkın yatağına girme.','balık olta misina')
add('GIDA','Balıkta saklama ve parazit riski','Çiğ veya yeterince pişmemiş tatlı su balığı parazit taşıyabilir. | Soğuk zincir yoksa balığı uzun süre saklama; kısa zamanda güvenli biçimde pişir. | Kaynağı bilinmeyen veya kirlilik şüphesi olan sulardan balık yeme.','balık parazit pişirme')
add('GIDA','Av ve tuzakların etik ve yasal sınırları','Yaban hayatı koruma ve av yasaları afet dışı zamanda da geçerlidir. | Tuzaklar insanlar ve evcil hayvanlar için ciddi yaralanma riski yaratabilir. | İmkân varsa stok gıda ve yasal olta gibi düşük riskli yöntemleri öncele.','av tuzak güvenlik')
add('GIDA','Bilinmeyen bitkiyi tüketmeme','Bitkinin tek fotoğrafı, benzer zehirli türleri elemek için yeterli değildir. | Bölgesel ad, büyüme evresi ve tek tek ayırt edici özellikler doğrulanmadan yemeyi deneme. | Tüketim sonrası zehirlenme şüphesinde 112 veya zehir danışma hizmetine başvur.','yenebilir ot zehirli benzer')
add('GIDA','Bilinmeyen mantarı tüketmeme','Mantarlar fotoğraftan veya halk arasında kullanılan renk/gümüş-kaşık testleriyle güvenle tanınamaz. | Ölümcül zehirli benzerleri olabilir; deneyim ve uzman onayı yoksa tüketme. | Zehirlenme şüphesinde belirtileri beklemeden acil yardım iste.','mantar zehirlenme',priority='yüksek')
add('GIDA','Besin enerjisi planı','Önce eldeki güvenli ve bozulma riski az gıdaları say. | Ağır eforu, su ve hava durumunu birlikte değerlendirerek tüketimi planla. | Çocuk, gebe, kronik hastalığı olan ve fiziksel çalışma yapanların gereksinimleri farklıdır.','kalori beslenme plan')
# Health (non-prescriptive)
add('SAĞLIK','Acil sağlık taraması','Önce çevre güvenliğini değerlendir; bilinci, normal solunumu ve ağır kanamayı kontrol et. | Bilinç kaybı, nefes almama, şiddetli kanama, felç bulgusu gibi durumlarda 112. | İlk yardım eğitimli değilsen acil operatörün yönlendirmesini izle.','bilinç solunum kanama 112',ref=['AHA'],priority='yüksek')
add('SAĞLIK','Göğüs ağrısı ve nefes darlığı','Yeni veya şiddetli göğüs ağrısı, nefes darlığı, soğuk terleme ve bayılma ciddi olabilir. | Kişiyi zorlayarak yürütme; 112’yi ara ve talimatları uygula. | Evde ilaç deneme veya internet olmamasını gerekçe göstererek bekleme.','göğüs ağrısı kalp nefes',priority='yüksek')
add('SAĞLIK','İnme belirtileri','Yüzde kayma, kolda güçsüzlük ve konuşmanın bozulması inme belirtisi olabilir. | Başlangıç saatini not et ve derhal 112’yi ara. | Ağızdan yiyecek, içecek veya ilaç verme.','felç inme yüz kol konuşma',priority='yüksek')
add('SAĞLIK','Şiddetli alerjik reaksiyon','Dudak/dil şişmesi, hırıltı, nefes güçlüğü, bayılma ve yaygın döküntü bir aradaysa anafilaksi olabilir. | Hemen 112’yi ara. | Kişinin önceden reçetelenmiş adrenalin otoenjektörü varsa kendi eylem planına/operatör yönlendirmesine göre kullanılması gerekebilir.','anafilaksi alerji dudak nefes',priority='yüksek')
add('SAĞLIK','Kirli su sonrası ishal','Kirli su sonrası ishal bir enfeksiyon belirtisi olabilir, tek bir nedene bağlanamaz. | Güvenli su ve uygun ORS ile sıvı kaybını önlemeye odaklan. | Kanlı dışkı, çok yüksek ateş, şiddetli ağrı, belirgin susuzluk veya içememe varsa acil tıbbi değerlendirme gerekir.','ishal kirli su oral rehidrasyon',ref=['WHO_ISHAL'],priority='yüksek')
add('SAĞLIK','Kesiklerde enfeksiyon riski','Yarayı mümkünse temiz akan suyla nazikçe temizle ve temiz pansumanla kapat. | Kızarıklığın yayılması, irin, artan ağrı veya ateş enfeksiyon düşündürebilir. | Derin/kirli yarada tetanos ve tıbbi değerlendirme gerekebilir.','kesik enfeksiyon tetanos')
add('SAĞLIK','Yanıkta temel yaklaşım','Yanıcı kaynaktan güvenle uzaklaş; yanığı serin akan suyla soğut. | Buz, diş macunu, yağ, rastgele krem sürme; yapışmış giysiyi zorla çekme. | Yüz, el, genital bölge, geniş veya derin yanıklarda tıbbi yardım iste.','yanık ilk yardım',ref=['AHA'])
add('SAĞLIK','Kafa travmasından sonra alarm','Bilinç kaybı, tekrarlayan kusma, nöbet, artan baş ağrısı, konuşma bozulması veya davranış değişikliği ciddidir. | Şüpheli boyun yaralanmasında gereksiz hareket ettirme. | Acil değerlendirme için 112’yi ara.','kafa travması sarsıntı nöbet',priority='yüksek')
add('SAĞLIK','Güneş çarpması ve ısı hastalığı','Aşırı sıcakta bilinç bulanıklığı, bayılma veya çok yüksek vücut ısısı tehlikelidir. | Kişiyi gölge/serin yere al ve acil yardım çağır; mümkün olan güvenli soğutmaya başla. | Bilinci bozuk kişiye ağızdan su verme.','sıcak çarpması güneş',priority='yüksek')
add('SAĞLIK','İlaç için güvenlik kontrolü','Etken madde, dozaj biçimi, son kullanma tarihi, saklama koşulu ve orijinal kutuyu kontrol et. | Başkasının reçeteli ilacını, bulunmuş etiketsiz tabletleri veya son kullanması geçmiş kritik ilaçları rastgele kullanma. | Alerji, gebelik, kronik hastalık ve mevcut ilaç etkileşimlerini sağlık uzmanına danış.','ilaç alerji etkileşim')
add('SAĞLIK','Ateşli çocukta acil belirtiler','Yaşa göre ateş değerlendirmesi değişir. | Solunum güçlüğü, sürekli uykuya meyil, ense sertliği, morarma, susuzluk veya havale varsa acil yardım iste. | Dozu bilinmeyen yetişkin ilacını çocuğa verme.','çocuk ateş havale susuzluk',priority='yüksek')
add('SAĞLIK','Sürekli kusma','Sıvı tutamama hızla susuzluğa neden olabilir. | Bilinç bulanıklığı, kanlı kusma, şiddetli karın ağrısı veya ciddi halsizlik varsa tıbbi yardım iste. | Bilinci azalmış kişiye yiyecek/içecek verme.','kusma dehidrasyon')
add('SAĞLIK','Psikolojik ilk yardım','Önce kişinin güvenliğini ve temel ihtiyaçlarını karşıla. | Sakin ve kısa cümlelerle konuş, zorla travma anlatmasını isteme; ailesi ve destek ağıyla temasını kolaylaştır. | Kendine zarar verme riski veya ciddi davranış değişikliği varsa acil profesyonel yardım al.','stres psikolojik ilk yardım')
# Medicine class reference - not dosage or prescription
add('İLAÇ','Amoksisilin: antibiyotik bilgisi','Penisilin grubundan reçeteli antibiyotiktir; bazı bakteriyel enfeksiyonlarda kullanılır. | Viral soğuk algınlığı için uygun değildir; gereksiz kullanım direnç oluşturur. | Penisilin alerjisi öyküsü kritik önem taşır. Reçetesiz kendi kendine başlama; doz/süre tanıya ve kişiye göre belirlenir.','amoksisilin penisilin antibiyotik alerji')
add('İLAÇ','Metronidazol: antibiyotik/antiprotozoal','Belirli bakteri ve parazit enfeksiyonlarında hekim tarafından seçilir. | İshalin her türünde kullanılmaz; doğru tanı gerekir. | İlaç etkileşimleri ve mevcut hastalıklar önemlidir; kendi kendine başlama.','metronidazol antibiyotik parazit')
add('İLAÇ','Doksisiklin: antibiyotik bilgisi','Bazı bakteriyel enfeksiyonlarda kullanılan reçeteli antibiyotiktir. | Yaş, gebelik, güneş hassasiyeti ve diğer ilaçlar kullanım kararında önem taşır. | Etiket ve hekim tavsiyesi olmadan alınmamalıdır.','doksisiklin antibiyotik')
add('İLAÇ','Azitromisin: antibiyotik bilgisi','Belirli bakteriyel enfeksiyonlarda reçetelenir. | Kalp ritim sorunları ve ilaç etkileşimleri bazı kişilerde önemlidir. | Her öksürük, boğaz ağrısı veya ishal için otomatik seçim değildir.','azitromisin antibiyotik')
add('İLAÇ','Omeprazol: mide asidi baskılama','Proton pompası inhibitörüdür; belirli mide-asit sorunlarında kullanılır. | Tüm karın ağrılarının nedeni asit değildir. | Uzun süreli kullanım ve eşzamanlı ilaçlar açısından sağlık uzmanına danışılmalıdır.','omeprazol mide reflü')
add('İLAÇ','Salbutamol: inhaler bilgisi','Bazı hastalarda bronşları gevşetmek için reçetelenen kısa etkili inhaler ilaçtır. | Kişinin önceden tanısı ve reçetesi yoksa yeni gelişen nefes darlığını kendi kendine tedavi etmeye çalışma. | Ciddi nefes darlığında 112 çağır.','salbutamol inhaler astım')
add('İLAÇ','Adrenalin otoenjektörü: acil ilaç','Anafilaksi riski için kişiye özel reçetelenebilir. | Kullanım şekli cihaz modeline ve bireysel acil eylem planına bağlıdır. | Anafilaksi şüphesinde otoenjektör kullanılmış olsa da 112 aranmalıdır.','adrenalin anafilaksi otoenjektör',priority='yüksek')
add('İLAÇ','Aspirin: etken madde bilgisi','Ağrı/ateş ve bazı damar hastalıklarında farklı amaçlarla kullanılır. | Kanama, ülser, alerji, çocuk yaşı ve başka ilaçlarla etkileşim açısından riskleri vardır. | Her göğüs ağrısında veya her hasta için otomatik kullanılmaz; acil operatörün yönlendirmesini izle.','aspirin asetilsalisilik asit kanama')
add('İLAÇ','Antikoagülan ilaçlar','Varfarin, apiksaban ve benzeri ilaçlar pıhtılaşmayı etkiler; ciddi kanama riski taşıyabilir. | Dozun atlanması ya da çift doz alınması tehlikeli olabilir. | Kafa travması, kanlı dışkı, kontrol edilemeyen kanama gibi durumlarda acil yardım gerekir.','varfarin apiksaban kan sulandırıcı')
add('İLAÇ','İnsülin: saklama ve güvenlik','İnsülin tipi, doz ve enjeksiyon zamanlaması hastaya özeldir. | Sıcaklık ve donma ilacın etkinliğini etkileyebilir; ürün etiketindeki saklama bilgisine uy. | Bilinç kaybı ve şiddetli hipoglisemi acildir; başka kişinin insülinini kullanma.','insülin diyabet saklama')
add('İLAÇ','Antihistaminikler: kuşaklar ve uyarılar','Alerji belirtilerinde kullanılan farklı antihistaminikler vardır; bazıları belirgin uyku yapabilir. | Sürüş, uykuya eğilim, yaş ve diğer ilaçlar seçimde önemlidir. | Solunum sıkıntısı ve dil/dudak şişmesi varsa antihistaminik tek başına acil tedavi değildir.','antihistaminik alerji uyku')
add('İLAÇ','İlaç kutusundaki ibareleri okuma','Etken madde, mg/ml, tablet/kapsül/şurup, son kullanma, parti no ve saklama sıcaklığı ayrı bilgilerdir. | Aynı marka adı farklı ülkelerde veya formlarda farklı içerik taşıyabilir. | Prospektüs ve resmî ürün bilgisini temel al; etiketsiz hapı kullanma.','prospektüs kutu etken madde')
# Regional flora risk
add('BÖLGE','Ege: yaz sıcağı ve yangın hattı','Makilik ve ormanlık arazide yazın yangın tehlikesi, su kıtlığı ve sıcak çarpması öne çıkar. | Tahliye güzergâhını, gölgeyi ve güvenilir su kaynağını önceden belirle. | Yangın sırasında rüzgâr yönü değişebilir; dumanlı hatta yaklaşma.','ege izmir manisa aydın',region=['EGE'])
add('BÖLGE','Marmara: deprem ve yoğun yerleşim','Hasarlı yapılar, doğalgaz ve yoğun trafik afet sonrasında ek risk oluşturur. | Önceden belirlenmiş toplanma alanları ve güvenli yürüyüş yollarını kullan. | Sahil kesimlerinde ilgili resmî tsunami uyarılarını da dikkate al.','marmara istanbul deprem',region=['MARMARA'])
add('BÖLGE','Akdeniz: sıcak ve ani yağış','Sıcak çarpması, orman yangını, kuru dere yataklarında ani taşkın riski birlikte görülebilir. | Kıyı ve dağ geçişlerinde rüzgâr/hava değişimini gözet. | Dere yatağında çadır kurma.','akdeniz antalya adana',region=['AKDENİZ'])
add('BÖLGE','Karadeniz: heyelan ve sel','Yoğun yağışta vadi tabanı, dere kenarı ve dik yamaçların altından uzak dur. | Doymuş toprak ve çatlayan yamaç heyelan riski işareti olabilir. | Akıntılı sudan geçmeye çalışma.','karadeniz trabzon rize',region=['KARADENİZ'])
add('BÖLGE','İç Anadolu: gece-gündüz farkı','Gündüz kurak/sıcak, gece soğuk olabilir; katmanlı giysi ve su planı önemlidir. | Açık arazide rüzgâr koruması ara; yıldırımda tek başına duran ağaç altına sığınma. | Kışın uzun süre hareketsiz kalma ve ıslanmadan kaçın.','iç anadolu konya ankara',region=['İÇ ANADOLU'])
add('BÖLGE','Doğu Anadolu: yüksek rakım','Soğuk, yoğun kar, çığ ve ulaşım kesintisi bölgeye göre öne çıkabilir. | Kar birikmiş eğimli yüzeylerden ve çığ potansiyelli hatlardan uzak dur. | Yüksek rakımda su kaynatma süresini uygun seç.','doğu anadolu erzurum kars',region=['DOĞU ANADOLU'])
add('BÖLGE','Güneydoğu: sıcak ve su yönetimi','Yazın sıcak hava, su kaybı ve açık güneş altında çalışma riski artar. | Gölge, dinlenme ve yeterli güvenli içme suyu planla. | Uzun yürüyüşleri sıcak saatlere denk getirmekten kaçın.','güneydoğu gaziantep diyarbakır',region=['GÜNEYDOĞU ANADOLU'])
# New modules: hygiene, comms, energy, nav, tools, food cultivation
add('HİJYEN','El yıkama olmadan bulaş riski','Tuvalet sonrası ve gıda hazırlamadan önce temiz su ve sabun kullan. | Kirli ellerle içme suyuna, pişmiş yiyeceğe ve yara pansumanına temas etme. | Güvenilir su kısıtlıysa gıda hazırlama ve el temizliği için miktar ayır.','el sabun bulaş enfeksiyon')
add('HİJYEN','Tuvalet ve yaşam alanının ayrılması','Atıkları içme suyu kaynağından, yemek pişirme ve uyku alanından uzak tut. | Sızıntı, taşkın ve hayvanların dağıtma riskini değerlendir. | Çocukların atıklarla temasını engelle; yerel resmî sanitasyon talimatlarını uygula.','tuvalet kanalizasyon hijyen')
add('HİJYEN','Gri su ile içme suyunu ayırma','Bulaşık, çamaşır ve yüzey temizliğinden çıkan gri suyu içme suyu kabına koyma. | İçilebilir suyu farklı kap ve renkle etiketle. | Kirli yüzeylerden akan suyu gıdaya temas ettirme.','gri su içme suyu')
add('HİJYEN','Kemirgen ve böceklerden korunma','Gıda kaplarını kapalı ve kuru tut; açık yemek artığı bırakma. | Isırık, dışkı veya idrar şüphesiyle kirlenmiş gıdayı tüketme. | Çatlakları kapatmak ve uyku yerini temiz tutmak yararlı olabilir.','kemirgen haşere')
add('HİJYEN','Çöplerin ayrılması','Kesici-delici, tıbbi, gıda ve yanıcı atıkları mümkünse ayrı ve sağlam kaplarda topla. | Kullanılmış iğneleri elle geri kapatma veya gelişigüzel atma. | Yangına hassas pilleri kısa devre ettirecek biçimde metal atıkla karıştırma.','çöp atık kesici pil')
add('İLETİŞİM','İnternetsiz iletişim seçenekleri','FM/AM radyo ile resmî duyuruları dinleyebilirsin; pili ve alternatif frekansları hazır tut. | Kısa mesafe telsiz/PMR446 kullanımında geçerli kurallara ve kanal paylaşımına uy. | Cihaz çekim mesafesi arazi koşullarına bağlıdır, erişim garanti edilmez.','fm am telsiz pmr446 radyo')
add('İLETİŞİM','Telsizle kısa durum raporu','Konum, kişi sayısı, acil tehlike, ihtiyaç ve geri dönüş için kısa ve anlaşılır mesaj hazırla. | Kanalları uzun konuşmalarla meşgul etme; yardım çağrılarını önceliklendir. | Yanlış veya doğrulanmamış afet haberini yayma.','telsiz mesaj rapor')
add('İLETİŞİM','Acil durumda telefon pili koruma','Ekran parlaklığını düşür; gereksiz uygulamaları, Bluetooth ve arka plan trafiğini kapat. | Resmî bilgi ve acil haberleşme dışında uzun görüşmelerden kaçın. | Telefonu aşırı sıcakta veya soğukta bırakma.','telefon pil şarj')
add('İLETİŞİM','Aile iletişim kartı','Acil numaraları ve bir dış şehir irtibatını basılı kartta ve cihazın çevrimdışı notlarında sakla. | Buluşma yerini, alternatif rotayı ve mesajlaşma planını önceden paylaş. | Ortak kullanılan cihazlara hassas kimlik bilgilerini kaydetme.','aile telefon acil iletişim')
add('İLETİŞİM','SOS sinyali ve işaretleme','Önce güvenliğin, konumun ve çevrenin tehlikelerini kontrol et. | Işık, düdük ve belirgin işaretleri kurtarma ekibinin görebileceği güvenli konumda kullan. | Orman yangını riski olan ortamda sinyal ateşi yakma.','sos sinyal düdük ışık')
add('ENERJİ','Güneş panelinde güç hesabı','Panelin etiketindeki W değeri ideal koşullardaki nominal gücüdür; bulut ve gölge üretimi azaltır. | Günlük enerji tahmini için ortalama W × çalışma saati hesabıyla başla. | Akü ve dönüştürücü kayıpları nedeniyle enerji bütçesine pay bırak.','solar panel watt wh hesap')
add('ENERJİ','W, Wh, V ve Ah kavramları','W anlık güç; Wh toplam enerjidir. | Örnek: 5 W tüketim 10 saatte yaklaşık 50 Wh kullanır. | Bataryanın Ah değerini Wh’ye çevirmek için nominal voltajla çarp; verim ve kapasite kaybını hesaba kat.','volt amper watt wh ah')
add('ENERJİ','Bataryayı güvenle şarj etme','Pil kimyasıyla uyumlu şarj kontrolcüsü kullan; lityum, LiFePO4 ve kurşun-asit şarj profilleri farklıdır. | Sigorta, kutup koruması ve uygun kablo kesiti gereklidir. | Şişen, hasarlı veya aşırı ısınan pili kullanma.','batarya lityum lifepo4 şarj')
add('ENERJİ','Jeneratör güvenliği','Jeneratörü kapı, pencere veya havalandırma girişlerinden uzak açık havada kullan. | Kapalı garaj, balkon girintisi veya çadır içinde çalıştırma; karbonmonoksit ölümcül olabilir. | Yakıt eklemeden önce güvenle durdurup soğumasını bekle.','jeneratör karbonmonoksit',priority='yüksek')
add('ENERJİ','Enerji tüketim planı','Aydınlatma, haberleşme, bilgi terminali ve kritik tıbbi ekipmanı önem sırasına diz. | Gücü yalnız gereken saatlerde aç; ekran parlaklığını azalt. | Kalan Wh kapasiteyi günlük planla karşılaştır.','güç yönetimi batarya')
add('ENERJİ','USB güç kaynaklarında uyumluluk','5V cihazın doğru voltaj ve yeterli akımla beslendiğini kontrol et. | Yanlış voltaj elektronik kartı bozabilir; dönüştürücünün çıkışını ölçerek doğrula. | Kalitesiz kablo ve gevşek konnektör gerilim düşüşüne yol açabilir.','usb 5v regulator raspberry')
add('NAVİGASYON','Pusula ve harita yönlendirmesi','Pusulanın kuzeyi ile haritadaki kuzey işaretini eşleştir. | Metal araç ve mıknatıslar pusulayı saptırabilir. | Araziye girmeden dönüş güzergâhı ve su noktalarını belirle.','pusula harita kuzey')
add('NAVİGASYON','GPS yokken yol kaydı','Ayrılırken rota, tahmini saat, yön ve son bilinen konumu basit bir kâğıda yaz. | İşaretlenmiş patika ve güvenli güzergâhtan ayrılma. | Tanıdık rota yoksa karanlıkta veya tehlikeli arazide gereksiz yürüyüşten kaçın.','gps yön kaybolma')
add('NAVİGASYON','Koordinat formatı','Enlem-boylam ondalık derece veya derece-dakika-saniye biçiminde yazılabilir. | Gönderdiğin koordinatın formatını da belirt, yanlış işaret çıkmasını önle. | Koordinatı haritadan tekrar doğrula.','koordinat enlem boylam')
add('NAVİGASYON','Toplanma alanını önceden kaydet','AFAD/e-Devlet üzerinden resmî toplanma alanını afet öncesinde sorgula. | Adresini, koordinatını ve iki alternatif erişim yolunu çevrimdışı not et. | Resmî uyarı nedeniyle alan değişmişse güncel yönlendirmeyi izle.','afad toplanma alanı',ref=['AFAD_TOPLANMA'])
add('NAVİGASYON','Tehlikeli arazi işaretleri','Kopmuş elektrik hattı, akıntılı su, gevşek kaya, çatlak yamaç veya yoğun duman olan alandan uzak dur. | Şüpheli köprü ve duvarların altından geçme. | Bilmediğin arazide kestirme yapmak riskli olabilir.','heyelan kaya köprü geçiş')
add('ONARIM','Temel alet envanteri','Çok amaçlı tornavida, pense, eldiven, bant, ip ve küçük aydınlatma taşı. | Kesici aletleri kılıfında sakla; kişisel koruyucu ekipman kullan. | Önce güvenli ve basit onarımları yap; riskli elektrik/gaz işlerine girişme.','tamir pense tornavida')
add('ONARIM','Elektrik kaçağı şüphesi','Su basmış panoya, açık iletkene ve düşmüş elektrik hattına dokunma. | Enerji kesildiğini yalnız gözle varsayma; ehil kişi kontrol etmelidir. | Elektrik çarpması veya yangın riski varsa alanı boşalt ve yetkililere haber ver.','elektrik kısa devre pano',priority='yüksek')
add('ONARIM','İp ve branda bakımı','İplerin yıpranma, kopma, düğüm ve aşınma noktalarını kontrol et. | Branda deliklerini su girişini engelleyen uygun malzemeyle onar. | İnsan kaldırma veya yüksekten çalışma için amatör ekipman kullanma.','ip branda onarım')
add('ONARIM','İçme suyu kabı onarımı','Gıda temasına uygun olmayan yapıştırıcı veya bilinmeyen plastikleri içme suyuna temas ettirme. | Çatlak, kirlenmiş veya kimyasal taşımış bidonu içme suyu için kullanma. | Güvenilir temiz kap yoksa ambalajlı suyu korumaya öncelik ver.','su kabı plastik tamir')
add('TOPLULUK','Küçük grup görev dağılımı','Güvenlik, su, sağlık kontrolü, yemek ve iletişim sorumluluklarını belirle. | Çocukları ve özel desteğe ihtiyacı olanları gözet. | Günlük kısa durum toplantısında stok ve yeni riskleri kaydet.','grup yönetimi görev')
add('TOPLULUK','Ortak su ve gıda kayıt defteri','Günlük giriş-çıkış miktarını, hangi kaynağın kullanıldığını ve saklama koşulunu yaz. | Kimse için tıbbi özel bilgileri açık ilan panosuna asma. | Su şüphesinde kaynağı işaretleyip kullanımdan çıkar.','envanter su gıda')
add('TOPLULUK','Afet bilgisi doğrulama','Resmî duyuruyu, kaynağın yayın tarihi ve kapsadığı bölgeyi kontrol et. | Tek kişinin aktardığı söylentiyi kesin bilgi gibi paylaşma. | Çelişkide güvenilir yetkili açıklamasını ara; çevrimdışı arşivin güncelliğini sorgula.','doğrulama bilgi kirliliği')
add('TOPLULUK','Çocuklarla kriz iletişimi','Kısa, yaşa uygun ve doğru açıklama yap; sahte güvence verme. | Rutini ve güvenlik hissini destekle; çocuğun sorularını dinle. | Ayrılma riskine karşı iletişim/buluşma planını öğret.','çocuk kriz psikoloji')
add('TOPLULUK','Komşu destek kontrolü','Yaşlı, yalnız yaşayan ve hareket kısıtlılığı olan komşuların yardım isteğini güvenli koşullarda kontrol et. | Yetkili arama-kurtarma ekiplerinin işini engelleme; riskli binaya kontrolsüz girme. | İhtiyaçları açık ve kısa şekilde kayıt altına al.','komşu destek yaşlı')
